def bfs_find_component(r, c, grid, bg):
    comp_cells = []
    color = grid[r][c]
    if color == bg:
        return None

    visited = set()
    queue = deque([(r, c)])

    while queue:
        cr, cc = queue.popleft()
        if (cr, cc) in visited:
            continue
        visited.add((cr, cc))
        comp_cells.append((cr, cc))

        for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
            nr, nc = cr + dr, cc + dc
            if 0 <= nr < h and 0 <= nc < w:
                if grid[nr][nc] == color and (nr, nc) not in visited:
                    queue.append((nr, nc))

    min_r, max_r = min(cr for cr, cc in comp_cells), max(cr for cr, cc in comp_cells)
    min_c, max_c = min(cc for cr, cc in comp_cells), max(cc for cr, cc in comp_cells)
    rect_area = (max_r - min_r + 1) * (max_c - min_c + 1)
    is_rect = rect_area == len(comp_cells)

    return {'color': color, 'cells': comp_cells, 'rect': (min_r, min_c, max_r, max_c), 
            'is_rectangular': is_rect}

